- 科技水平一度世界第二。

#### 2. **统治方式：更严密的控制**
- 集体农庄 = 新农奴制；
- 古拉格 = 国家强制劳动营；
- 克格勃 = 全民监控系统；
- 言论审查、思想改造、消灭异见。

👉 **用最先进的生产力，维持最严酷的统治**。

> 正如索尔仁尼琴在《古拉格群岛》中写的：  
