### 六、为什么“统治方式不变”？因为权力逻辑没变

你问：**为什么技术变了，统治不变？**

因为——

| 项目 | 欧洲（英法德） | 俄罗斯 |
|------|----------------|--------|
| 现代化动力 | 市民社会、资本、议会推动 | 沙皇/党国自上而下强制 |
| 权力来源 | 法律、选举、社会契约 | 暴力、意识形态、个人权威 |
| 人民角色 | 公民（有权利） | 臣民/劳动者（有义务） |
| 改革目的 | 自由 + 富强 | **只求富强，不求自由** |

👉 所以，俄罗斯的现代化，从来不是为了“解放人”，  
而是为了**让国家强大，能打仗、能扩张、能对抗外敌**。

