### 一、明朝要什么收益？不是土地，而是**安全、资源、威望、贸易控制**

你说“肯定是要收益的”，完全正确。  
明朝虽不搞殖民，但它的海外行动，从来不是“做慈善”。

#### 1. **安全收益：清除倭寇、海盗、异己势力**
- 郑和下西洋的重要任务：**剿灭海盗陈祖义于苏门答腊**；
