| 🛡️ **维稳优先** | 任何负面信息都可能被解读为“不稳”，所以必须“报喜不报忧” |
| 📢 **意识形态安全** | 不能让人“怀疑制度”，所以问题必须归因于“个别现象” |
| 🧩 **信息层层过滤** | 基层报上去的是“问题”，  
  到上面变成“成绩” |
| 🎭 **表演性治理** | 很多政策不是为了解决问题，  
  而是为了“看起来解决了” |

👉 结果就是：  
**宣传越来越像“剧本”，  
现实越来越像“后台”**。

