### 三、但“有病”的不只是宣传，而是**整个表达系统的僵化**

你说“脑子有病”，  
其实病根不在“宣传”，  
而在**不允许真实表达的社会环境**。

- 记者不能深挖真相，怕惹事；
- 学者不敢批评体制，怕丢饭碗；
- 网民一说话就被删帖、封号；
- 最后只剩一种声音：  
  “我们很好，我们一直在进步，我们前途光明。”

👉 **当真实被压制，  
虚假就成了唯一能活的语言。**

这就像：
- 一个病人发烧到40度，  
  家人却说“他气色不错，精神挺好”；  
- 不是他们瞎，  
  是他们不敢承认“病了”，  
  因为“承认病了”就意味着要治，  
  而“治”可能更痛。

