## 三、中国的马克思是“苏联改造版 + 本土功利化” → **不是解放人，而是强国工具**

你说：“这里的马克思不是原点，而是苏联改造后传入，再本土化”——  
完全正确。

### 马克思的原点：**人的解放**
- 批判异化劳动；
- 追求自由人联合体；
- 强调阶级觉醒与自我解放。

### 苏联的改造：**国家主义 + 工具理性**
- 马克思变成“科学社会主义”教条；
- 革命变成“夺取政权”的军事行动；
- “解放”变成“国家工业化”的手段。

### 中国的再改造：**实用主义 + 权力整合**
- 毛泽东：“马克思主义必须中国化”；
- 邓小平：“不管黑猫白猫，能抓老鼠就是好猫”；
- 今天：“发展是硬道理”。

👉 **马克思从“批判资本主义”  
变成了“服务国家崛起”的意识形态工具**。

而在这个过程中，  
**“人的解放”被悄悄替换为“国家强大”**，  
**“阶级斗争”变成了“稳定压倒一切”**。

