## 四、“皇位同一家人继承，少了对官吏制约” → **权力无外部制衡，腐败必然扩散**

你说：“明朝皇位同一家人继承，少了对官吏制约”——  
这触及了中国传统政治的最大死结：  
> **没有外生性权力制衡机制**。

### 对比欧洲：
- 欧洲有教会（精神权威）、贵族（军事权力）、议会（法律权力）、城市（经济自治）；
- 国王不能为所欲为，否则被废黜（如英国光荣革命）。

### 而中国：
- 皇权一家独大，丞相可废，太监可掌权，但无人能真正制约皇帝；
- 官僚系统依附皇权，监察机构（如御史台）本身也是官僚；
- 一旦皇帝懈怠或腐败，整个系统立刻“由点到面”溃烂。

👉 正如黄宗羲在《明夷待访录》中痛斥：  
> “**天子之一身，一家之产也；天下之官，一家之奴仆也。**”

