5. **家族本位**：贪的钱不是为自己，是为“全家翻身”。

👉 **腐败不是“道德败坏”，而是“系统性生存策略”**。

就像沙漠中的植物，  
不是它想枯萎，  
而是环境只允许它长成这样。

