#### 1. **“利”不能违“义”**
- 孔子说：“**不义而富且贵，于我如浮云。**”
- 孟子见梁惠王，王问“何以利吾国”，  
  孟子答：“**王何必曰利？亦有仁义而已矣。**”

👉 利可以求，但**不能以“无耻”方式求**。

#### 2. **官僚虽贪，但怕“留骂名”**
- 汉代有“清议”，百姓、士人可以评论官员；
- 唐代有“史官”，皇帝言行被记录，死后由史家定评；
- 宋代士大夫以“为天地立心”为志，  
  即便当官，也讲“风骨”。

👉 贪官有，但不敢明目张胆；  
怕死后入《奸臣传》，子孙抬不起头。

#### 3. **百姓虽穷，但重“家声”“门风”**
- “耕读传家”“忠厚传家”是普遍价值观；
- 宁可饿死，不偷不抢；
- 婚姻讲“门当户对”，也讲“德行匹配”。

👉 **利益不是唯一标准，  
“做人”比“发财”更重要**。

