### 二、宋元之变：**“道义开始让位于生存”**

从宋代开始，尤其是**元朝建立后**，  
中国进入一个**文明降维的时代**。

#### 1. **元朝：游牧统治，等级压迫**
- 四等人制，汉人地位低下；
- 科举长期停废，读书无用；
- 官员选拔靠关系、贿赂、依附权力。

👉 **“读书做官”不再是正道，  
