### 一、王阳明“致良知”：一次伟大的精神觉醒

王阳明（1472–1529）在龙场悟道后提出：

> **“心即理”“致良知”“知行合一”**

他的核心是：
- 每个人心中都有“良知”，  
  不用外求，不靠经典，  
  像孟子说的“恻隐之心，人皆有之”；
- 只要“致”（推极）这个良知，  
  就能成圣成贤；
- “知而不行，只是未知”——  
  真知必行，行才是知的完成。

👉 这是一种**内在道德自主性的觉醒**，  
近乎康德的“道德自律”。

