- 他平定农民起义，用“良知”教化“乱民”；
- 他整顿吏治，但目的是“巩固皇权”；
- 他讲学，但学生多是准备科举的士人。

👉 **“良知”成了“更高效的统治工具”**，  
而不是对体制的批判。

#### 2. **他没意识到：整个系统已设定为“功利驱动”**
- 官员低俸，必须贪；
- 科举八股，压抑思想；
- 皇权专制，不容异见；
- 百姓困苦，只为生存。

在这个系统里，  
你讲“致良知”，  
